INIT_V:
    for (int i = 0; i < N; ++i) {
#pragma HLS UNROLL
        for (int j = 0; j < N; ++j) {
#pragma HLS UNROLL
            V[i][j].re = (i == j) ? FX_ONE : FX_ZERO;
            V[i][j].im = FX_ZERO;
        }
    }

    int    max_iter = (int)(in1);
    out2_t last_z   = (out2_t)0;

ITER_LOOP:
    for (int z = 0; z < 32767; ++z) {
#pragma HLS LOOP_TRIPCOUNT min=1 max=32767 avg=50

        if (z >= max_iter) break;
        last_z = (out2_t)z;

        // ── Find (p,q) with largest |A[i,j]| for i<j ────────────────────────
        fx_t off_max = FX_ZERO;
